package harness

import (
	"fmt"
	"slices"
	"strings"
)

// UnknownError reports a harness id the roster does not recognize.
//
// It is a type rather than a formatted string so manifest validation can
// recognise the condition — and attribute it to the asset entry or the
// `harnesses` list that produced it — without matching on message text.
type UnknownError struct {
	// ID is the unrecognized id exactly as it was written, so the message can
	// quote the manifest back to its author rather than paraphrase it.
	ID ID

	// Recognized is every id the roster does recognize, in the roster's order.
	// It is captured rather than looked up at render time so the error stays a
	// complete diagnostic wherever it is finally printed.
	Recognized []ID
}

// Error states the problem and the edit that fixes it, in that order, as every
// user-facing diagnostic does.
//
// Listing the recognized ids is most of the fix: the failure is almost always a
// misspelling or a harness harnaas does not support yet, and those two need
// different responses from the author.
func (e *UnknownError) Error() string {
	names := make([]string, 0, len(e.Recognized))
	for _, id := range e.Recognized {
		names = append(names, string(id))
	}

	return fmt.Sprintf(
		"unknown harness %q\n\n"+
			"Use a harness harnaas recognizes: %s.",
		e.ID, strings.Join(names, ", "),
	)
}

// IDs returns every recognized harness id in the roster's order.
//
// Callers get a fresh slice, because this list is rendered into user-facing
// errors and sorted into manifests; a caller that reorders it in place would
// change what every later message says.
func IDs() []ID {
	ids := make([]ID, 0, len(roster))
	for _, h := range roster {
		ids = append(ids, h.ID)
	}
	return ids
}

// All returns every recognized harness in the roster's order.
//
// The returned entries are copies down to their evidence slices, so the roster
// cannot be edited through a value a caller was handed.
func All() []Harness {
	all := make([]Harness, 0, len(roster))
	for _, h := range roster {
		all = append(all, clone(h))
	}
	return all
}

// Lookup returns the harness with the given id, or an *UnknownError naming the
// input and listing what harnaas does recognize.
func Lookup(id ID) (Harness, error) {
	for _, h := range roster {
		if h.ID == id {
			return clone(h), nil
		}
	}
	return Harness{}, &UnknownError{ID: id, Recognized: IDs()}
}

// Recognized reports whether id names a harness in the roster. It is the
// question to ask where the answer is a branch rather than a diagnostic; where
// it is a diagnostic, call Lookup and return its error, which already names the
// input and the alternatives.
func Recognized(id ID) bool {
	return slices.ContainsFunc(roster, func(h Harness) bool { return h.ID == id })
}

// HasPerUserLocation reports whether the harness reads assets from an
// unambiguous per-user location. This is the query manifest scope validation
// calls to decide whether an asset may declare `user` scope for this target.
//
// An unrecognized id is an error and never a false: "harnaas does not know this
// harness" and "this harness has no per-user location" call for different edits
// from the author, and collapsing them would report the second for a typo.
func HasPerUserLocation(id ID) (bool, error) {
	h, err := Lookup(id)
	if err != nil {
		return false, err
	}
	return h.PerUserLocation, nil
}

// clone copies a roster entry and its evidence slice, so a caller holding the
// result shares no backing array with the roster.
func clone(h Harness) Harness {
	h.ProjectEvidence = slices.Clone(h.ProjectEvidence)
	return h
}

// Package harness is harnaas's roster of the harnesses it recognizes.
//
// The roster is data only: an id, a display name, whether the harness has an
// unambiguous per-user location, and the observable evidence that a project is
// already using it. It maps nothing to a destination and it writes nothing. The
// adapters that turn an asset into a file on disk arrive with `harnaas install`
// and attach themselves to these ids.
//
// That seam is deliberate. Three things in this change need to know a harness
// exists — manifest validation must reject an unrecognized target, scope
// validation must know whether `user` scope has anywhere to go, and `init` must
// detect which harnesses a project already uses — while none of them needs to
// know where a skill lands. Deferring the roster until the adapters exist would
// force the manifest to accept any string as a harness name and reject it two
// phases later, at a point where the error can no longer name the line that
// caused it.
//
// A harness in the manifest's `harnesses` list is a guarantee, not an
// observation: it means "we guarantee the declared assets work for this
// harness". Because skills and instructions land in shared locations that
// several harnesses read, a harness absent from the list will still see assets
// installed for one that is present. That is why an unrecognized name is an
// error — it is a guarantee harnaas cannot make — and why an asset being
// visible to a harness nobody listed is not.
package harness

// ID is a harness's canonical identifier: the exact string a manifest writes in
// its `harnesses` list or an asset's `targets`, and the key an adapter will
// later register itself under.
//
// It is a named type rather than a bare string so a function taking a harness
// cannot silently be handed an asset id, a source key or a display name.
type ID string

// ClaudeCode is the only harness this change recognizes. More arrive with the
// adapters; the roster is where they are declared, one entry each.
const ClaudeCode ID = "claude-code"

// Default is the harness `harnaas init` scaffolds a manifest with when it
// detects none in the project. A default is what keeps init from ever writing
// an empty `harnesses` list, which would be a manifest that declares assets and
// guarantees them for nothing.
const Default = ClaudeCode

// Harness describes one recognized harness. Every field is data a caller reads;
// there is no behaviour here, and adding some is how the roster and the
// adapters start to disagree.
type Harness struct {
	// ID is the canonical identifier, and the only spelling a manifest may
	// use. Display names are never accepted as input.
	ID ID

	// DisplayName is what harnaas prints when it names the harness to a user.
	// It is never parsed, and never compared against manifest input.
	DisplayName string

	// PerUserLocation records whether the harness reads assets from an
	// unambiguous location in the user's home as well as from the project.
	//
	// This is what decides whether an asset may declare `user` scope for this
	// target. It is a property of the harness, not a preference: where a
	// harness has no single per-user root, or several that disagree, harnaas
	// has no correct answer and says so rather than guessing one.
	PerUserLocation bool

	// ProjectEvidence lists the project-root-relative paths whose presence
	// means the project is already using this harness. Any one of them is
	// enough.
	//
	// Evidence is observable state in the repository, never configuration the
	// user has not written yet: `init` runs before harnaas knows anything about
	// the project, so the only thing it can read is what the harness itself has
	// already left behind. The entries are paths rather than a predicate
	// because the roster stays data — `init` does the stat calls.
	ProjectEvidence []string
}

// roster is every recognized harness, ordered by ID.
//
// The order is the one callers see, so it has to be a property of the data
// rather than of how the literal happens to be written — a manifest error
// listing recognized harnesses must read identically on every run and every
// machine. TestRosterIsOrderedByID pins it, so an entry added in the wrong
// place fails a test instead of quietly reordering somebody's error message.
var roster = []Harness{
	{
		ID:              ClaudeCode,
		DisplayName:     "Claude Code",
		PerUserLocation: true,
		ProjectEvidence: []string{".claude", "CLAUDE.md"},
	},
}

package manifest_test

import (
	"strconv"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// TestParseAssetRefAcceptsBothForms covers the keyed remote form and the
// project-local form, which are the only two an asset entry may take.
func TestParseAssetRefAcceptsBothForms(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name      string
		source    string
		wantKey   string
		wantPath  string
		wantLocal bool
	}{
		{
			name:     "keyed remote form",
			source:   "acme:skills/review",
			wantKey:  "acme",
			wantPath: "skills/review",
		},
		{
			name:     "keyed form pointing at a file",
			source:   "acme:instructions/tone.md",
			wantKey:  "acme",
			wantPath: "instructions/tone.md",
		},
		{
			name:     "keyed form is cleaned without changing what it names",
			source:   "acme:./skills//review/",
			wantKey:  "acme",
			wantPath: "skills/review",
		},
		{
			name:      "project-local form",
			source:    ".harnaas/rules/house-style.md",
			wantPath:  ".harnaas/rules/house-style.md",
			wantLocal: true,
		},
		{
			name:      "project-local form staying inside .harnaas after cleaning",
			source:    ".harnaas/skills/../commands/ship",
			wantPath:  ".harnaas/commands/ship",
			wantLocal: true,
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()

			ref, violation := manifest.ParseAssetRef(0, test.source)
			require.Nil(t, violation)
			assert.Equal(t, test.wantKey, ref.SourceKey)
			assert.Equal(t, test.wantPath, ref.Path)
			assert.Equal(t, test.wantLocal, ref.Local())
		})
	}
}

// TestParseAssetRefRejects covers every string that is in neither form, plus
// the containment rules that must hold before any content is read.
func TestParseAssetRefRejects(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name      string
		index     int
		source    string
		wantParts []string
	}{

	}{
		{
			name:      "an unprefixed relative path states both accepted forms",
			source:    "skills/review",
			wantParts: []string{"neither of the two accepted forms", "acme:skills/review", ".harnaas/rules/house-style.md"},
		},
		{
			name:      "an empty source",
			index:     2,
			source:    "",
			wantParts: []string{"the asset entry at index 2", "declares no source"},
		},
		{
			name:      "a URL",
			source:    "https://example.com/skills/review",
			wantParts: []string{"neither of the two accepted forms"},
		},
		{
			name:      "a POSIX absolute path",
			source:    "/srv/assets/skills/review",
			wantParts: []string{"absolute path", "every asset source is relative"},
		},
		{
			name:      "a Windows absolute path is refused on every platform",
			source:    `C:\assets\skills\review`,
			wantParts: []string{"absolute path", "every asset source is relative"},
		},
		{
			name:      "a UNC path",
			source:    `\\share\assets\skills\review`,
			wantParts: []string{"absolute path"},
		},
		{
			name:      "a local path escaping .harnaas upward",
			source:    ".harnaas/../../etc/passwd",
			wantParts: []string{"does not stay inside .harnaas"},
		},
		{
			name:      "the .harnaas root itself is not an asset",
			source:    ".harnaas/",
			wantParts: []string{"does not stay inside .harnaas"},
		},
		{
			name:      "a keyed path leaving the source root",
			source:    "acme:../secrets/key",
			wantParts: []string{"leaves the root of the source", `"acme"`},
		},
		{
			name:      "a keyed form with an empty path",
			source:    "acme:",
			wantParts: []string{"neither of the two accepted forms"},
		},
		{
			name:      "a backslash separator is not a path separator harnaas accepts",
			source:    `acme:skills\review`,
			wantParts: []string{"separates its path with a backslash", `"/"`},
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()

			ref, violation := manifest.ParseAssetRef(test.index, test.source)
			require.NotNil(t, violation)
			assert.Equal(t, manifest.AssetRef{}, ref, "a rejected entry must not be half-parsed")
			assert.Equal(t, test.index, violation.Index)
			assert.Equal(t, assetFieldName(test.index), violation.Field)

			for _, part := range test.wantParts {
				assert.Contains(t, violation.String(), part)
			}
		})
	}
}

// TestCheckSourceKeyNamesTheKeyAndTheSourcesBlock covers the one rule that is a
// property of the document rather than of the string: the same asset entry is
// correct in one manifest and wrong in another.
func TestCheckSourceKeyNamesTheKeyAndTheSourcesBlock(t *testing.T) {
	t.Parallel()

	sources := map[string]manifest.Source{
		"acme":  {Key: "acme", Kind: manifest.SourceKindGitHub, Repository: "acme/assets", Ref: "v1.2.0"},
		"house": {Key: "house", Kind: manifest.SourceKindLocal, Repository: ".harnaas"},
	}

	declared, violation := manifest.ParseAssetRef(0, "acme:skills/review")
	require.Nil(t, violation)
	assert.Nil(t, manifest.CheckSourceKey(0, declared, sources))

	local, violation := manifest.ParseAssetRef(1, ".harnaas/rules/house-style.md")
	require.Nil(t, violation)
	assert.Nil(t, manifest.CheckSourceKey(1, local, sources), "the local form references no key")

	undeclared, violation := manifest.ParseAssetRef(2, "acmee:skills/review")
	require.Nil(t, violation)

	violation = manifest.CheckSourceKey(2, undeclared, sources)
	require.NotNil(t, violation)
	assert.Equal(t, 2, violation.Index)
	assert.Contains(t, violation.String(), `"acmee"`)
	assert.Contains(t, violation.String(), `"sources"`)
	assert.Contains(t, violation.String(), `"acme", "house"`, "the recognized keys are listed in a fixed order")
}

// TestCheckSourceKeyWithNoSourcesDeclared covers the manifest that declares no
// sources at all, where listing the keys that would have worked is not an
// available remedy.
func TestCheckSourceKeyWithNoSourcesDeclared(t *testing.T) {
	t.Parallel()

	ref, violation := manifest.ParseAssetRef(0, "acme:skills/review")
	require.Nil(t, violation)

	violation = manifest.CheckSourceKey(0, ref, nil)
	require.NotNil(t, violation)
	assert.Contains(t, violation.String(), `Declare "acme" in the "sources" block`)
}

// TestInferTypeAndID covers the inference the spec documents, in both entry
// forms, including the extension strip that makes `tone.md` and `tone` the same
// asset.
func TestInferTypeAndID(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name     string
		source   string
		wantType manifest.AssetType
		wantID   string
	}{
		{"skill from a keyed path", "acme:skills/review", manifest.AssetTypeSkill, "review"},
		{"rule from a keyed path", "acme:rules/house-style.md", manifest.AssetTypeRule, "house-style"},
		{"instruction from a local path", ".harnaas/instructions/tone.md", manifest.AssetTypeInstruction, "tone"},
		{"command from a keyed path", "acme:commands/ship", manifest.AssetTypeCommand, "ship"},
		{"persona from an agents directory", "acme:agents/reviewer", manifest.AssetTypePersona, "reviewer"},
		{"a nested source keeps the containing directory as the type", "acme:packs/skills/review", manifest.AssetTypeSkill, "review"},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()

			ref, violation := manifest.ParseAssetRef(0, test.source)
			require.Nil(t, violation)

			assetType, typeViolation := manifest.InferType(0, ref)
			require.Nil(t, typeViolation)
			assert.Equal(t, test.wantType, assetType)

			id, idViolation := manifest.InferID(0, ref)
			require.Nil(t, idViolation)
			assert.Equal(t, test.wantID, id)
		})
	}
}

// TestInferTypeRejectsAnUnrecognizedDirectory asserts the failure directs the
// author to the object form rather than guessing a type, because a wrongly
// typed asset installs somewhere nobody asked for and nobody notices.
func TestInferTypeRejectsAnUnrecognizedDirectory(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name   string
		source string
	}{
		{"a directory naming no type", "acme:prompts/review"},
		{"no containing directory at all", "acme:review"},
		{"the .harnaas root as the containing directory", ".harnaas/tone.md"},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()

			ref, violation := manifest.ParseAssetRef(3, test.source)
			require.Nil(t, violation)

			assetType, typeViolation := manifest.InferType(3, ref)
			require.NotNil(t, typeViolation)
			assert.Empty(t, string(assetType))
			assert.Equal(t, 3, typeViolation.Index)
			assert.Contains(t, typeViolation.String(), "names none of the asset types")
			assert.Contains(t, typeViolation.String(), `"skills/"`)
			assert.Contains(t, typeViolation.String(), `"agents/"`)
			assert.Contains(t, typeViolation.String(), `"type"`, "the remedy directs the author to the object form")
		})
	}
}

// TestInferIDSurvivesAnUnrecognizedDirectory is why type and id are inferred
// separately: an object declaring `type` for an unconventional layout still
// wants its id inferred, and must not be refused for a directory name nobody is
// relying on.
func TestInferIDSurvivesAnUnrecognizedDirectory(t *testing.T) {
	t.Parallel()

	ref, violation := manifest.ParseAssetRef(0, "acme:prompts/review.md")
	require.Nil(t, violation)

	_, typeViolation := manifest.InferType(0, ref)
	require.NotNil(t, typeViolation)

	id, idViolation := manifest.InferID(0, ref)
	require.Nil(t, idViolation)
	assert.Equal(t, "review", id)
}

// TestInferIDKeepsADotfileLeaf pins the one case where stripping the extension
// would leave nothing at all.
func TestInferIDKeepsADotfileLeaf(t *testing.T) {
	t.Parallel()

	ref, violation := manifest.ParseAssetRef(0, "acme:rules/.editorconfig")
	require.Nil(t, violation)

	id, idViolation := manifest.InferID(0, ref)
	require.Nil(t, idViolation)
	assert.Equal(t, ".editorconfig", id)
}

// TestAssetTypesAreStableAcrossCalls keeps the list a diagnostic is built from
// identical on every run, and keeps a caller from reordering it in place.
func TestAssetTypesAreStableAcrossCalls(t *testing.T) {
	t.Parallel()

	want := []manifest.AssetType{
		manifest.AssetTypeSkill,
		manifest.AssetTypeRule,
		manifest.AssetTypeInstruction,
		manifest.AssetTypeCommand,
		manifest.AssetTypePersona,
	}
	assert.Equal(t, want, manifest.AssetTypes())

	first := manifest.AssetTypes()
	first[0] = "mutated"
	assert.Equal(t, want, manifest.AssetTypes(), "a caller cannot reorder the list in place")
}

// assetFieldName spells the field a violation about an asset's source names, so
// the tests assert on what a reader would open rather than on the package's own
// formatting call.
func assetFieldName(index int) string {
	return "assets[" + strconv.Itoa(index) + "].source"
}

